/* ---- strips 1 + 2: FILT ---- */
.global _BQPFILT_01_02_process;
_BQPFILT_01_02_process:
    /* Both channels must be in steady state or there is no
     * pair: a staged coefficient set or a running crossfade
     * goes through the node's own reference path. */
    r1 = dm(_hpf_swap_pending_C1_FILT_01);
    r0 = dm(_lpf_swap_pending_C1_FILT_01);
    r1 = r1 or r0;
    r0 = dm(_filt_xfade_step_C1_FILT_01);
    r1 = r1 or r0;
    r0 = dm(_hpf_swap_pending_C1_FILT_02);
    r1 = r1 or r0;
    r0 = dm(_lpf_swap_pending_C1_FILT_02);
    r1 = r1 or r0;
    r0 = dm(_filt_xfade_step_C1_FILT_02);
    r1 = r1 or r0;
    r1 = pass r1;
    if ne jump (pc, .bqs_FILT_01_02);

    r2 = _filt_hpf_A_C1_FILT_01;
    r3 = _filt_state_A_C1_FILT_01;
    r8 = _filt_hpf_B_C1_FILT_01;
    r9 = _filt_state_B_C1_FILT_01;
    r0 = dm(_filt_active_C1_FILT_01);
    r0 = pass r0;
    if eq r8 = r2;
    if eq r9 = r3;
    r10 = BLK_CHAIN_B_P1;         /* strip A, odd pool */
#if DSP4_BQ_NEGCTL
    /* NEGATIVE CONTROL: give strip B strip A's coefficient
     * and state pointers, so the pair computes ONE channel
     * twice. The bus sum MUST differ, or the comparison that
     * says the paired graph is bit-exact was not testing
     * anything. */
    r11 = r8;
    r12 = r9;
#else
    r2 = _filt_hpf_A_C1_FILT_02;
    r3 = _filt_state_A_C1_FILT_02;
    r11 = _filt_hpf_B_C1_FILT_02;
    r12 = _filt_state_B_C1_FILT_02;
    r0 = dm(_filt_active_C1_FILT_02);
    r0 = pass r0;
    if eq r11 = r2;
    if eq r12 = r3;
#endif
    r13 = BLK_CHAIN_B;            /* strip B, base pool */
    r4 = 2;
    call _bq_pair_blk;
    rts;

.bqs_FILT_01_02:
    /* scalar fallback: both nodes work IN PLACE on their own
     * pool, so nothing has to be squared up afterwards. */
    call _C1_FILT_01_process;
    call _C1_FILT_02_process;
    rts;
_BQPFILT_01_02_process.end:

